-- PFMS organization invitation workspace for existing legacy organizations.
-- Returns only organizations that the current user may actually manage.
-- The invitation secret itself is still generated by pfms_create_legacy_invitation.

create or replace function public.pfms_list_my_manageable_legacy_organizations()
returns table (
  organization_id uuid,
  organization_name text,
  organization_type text,
  organization_status text,
  member_role text
)
language sql
stable
security definer
set search_path = ''
as $$
  select
    o.id,
    o.name,
    o.organization_type,
    o.status,
    m.role
  from public.organizations o
  join public.organization_memberships m
    on m.organization_id = o.id
  where m.user_id = auth.uid()
    and m.status = 'active'
    and public.can_manage_org(o.id)
  order by pg_catalog.lower(o.name);
$$;

revoke all on function public.pfms_list_my_manageable_legacy_organizations() from public, anon;
grant execute on function public.pfms_list_my_manageable_legacy_organizations() to authenticated;

comment on function public.pfms_list_my_manageable_legacy_organizations() is
  'Lists only legacy organizations where the authenticated user has an active manager membership.';
